"""Original NowRift item atlas, CC0. Reference sheets are inspiration, never copied."""
from PIL import Image,ImageDraw
from pathlib import Path
import math,random
out=Path('public/assets/items');out.mkdir(parents=True,exist_ok=True)
atlas=Image.new('RGBA',(256,192))
palettes=[('#b6c4a5','#7fae83','#4a695e'),('#d6b875','#ecce88','#866043'),('#a8c7d8','#84e5ec','#4f748f'),('#b19aaf','#f3a459','#644c65')]
for index in range(48):
 im=Image.new('RGBA',(32,32));d=ImageDraw.Draw(im);rng=random.Random(44+index)
 if index<24:
  world=index//6;slot=index%6;metal,gem,dark=palettes[world]
  if slot==0:
   if world in (0,2):
    d.line((7,27,23,7),fill='#352a2b',width=5);d.line((8,26,23,8),fill='#a48860',width=3);d.polygon([(17,8),(19,2),(25,2),(29,8),(25,14),(20,12)],fill=dark);d.polygon([(20,7),(23,3),(26,7),(24,12)],fill=gem);d.point((23,5),fill='#eff8d9');d.line((14,18,18,20),fill=metal,width=2)
   else:
    d.polygon([(7,25),(10,19),(22,3),(27,2),(27,7),(13,22)],fill=dark);d.polygon([(12,18),(24,4),(25,6),(15,20)],fill=metal);d.line((10,18,17,24),fill=gem,width=3);d.line((6,28,11,23),fill='#aa8054',width=3)
  elif slot==1:
   d.polygon([(9,5),(13,7),(19,7),(23,5),(29,11),(24,15),(23,27),(9,27),(8,15),(3,11)],fill=dark);d.polygon([(10,8),(13,10),(19,10),(22,8),(23,24),(9,24)],fill=metal);d.polygon([(16,11),(20,16),(16,22),(12,16)],fill=dark);d.line((11,26,22,26),fill=gem,width=2);d.line((5,9,9,7),fill=gem,width=2);d.line((23,7,27,10),fill=gem,width=2)
  elif slot==2:
   d.polygon([(6,23),(7,10),(12,5),(20,5),(25,11),(26,23),(20,26),(19,18),(13,18),(12,26)],fill=dark);d.polygon([(9,12),(13,7),(19,7),(22,12),(22,21),(10,21)],fill=metal);d.rectangle((11,14,21,17),fill='#263039');d.rectangle((15,8,17,13),fill=gem);d.line((8,23,11,24),fill=gem,width=2);d.line((21,24,24,23),fill=gem,width=2)
  elif slot==3:
   for x in [5,18]:
    d.polygon([(x,5),(x+8,5),(x+7,20),(x+10,24),(x+10,28),(x,28),(x-1,24)],fill=dark);d.rectangle((x+1,8,x+6,21),fill=metal);d.line((x,6,x+8,6),fill=gem,width=3);d.line((x+1,26,x+9,26),fill='#d7c09d',width=2);d.rectangle((x+3,12,x+4,18),fill=dark)
  elif slot==4:
   d.ellipse((5,7,27,28),fill=dark);d.ellipse((7,8,25,26),fill=metal);d.ellipse((11,13,21,22),fill=(0,0,0,0));d.polygon([(10,8),(16,2),(23,8),(17,15)],fill=dark);d.polygon([(12,8),(16,4),(21,8),(17,12)],fill=gem);d.point((16,6),fill='#eff8e8')
  else:
   pts=[(16+math.cos(a)*11,11+math.sin(a)*8) for a in [math.pi*(.08+i*.084) for i in range(11)]];d.line(pts,fill=dark,width=4);d.line(pts,fill=metal,width=2);d.polygon([(10,21),(16,15),(22,21),(17,29),(14,29)],fill=dark);d.polygon([(13,21),(16,18),(19,21),(16,26)],fill=gem);d.line((12,20,15,18),fill='#f1e3b0')
 elif index<40:
  n=index-24;color=['#ab895a','#92bf76','#c58f69','#c7ab79','#d6b957','#c89ba0','#86dce9','#aabadd','#c4a0ed','#df854c','#4f4e67','#e9a573','#8bc690','#e7be70','#9fcfe4','#e49b68'][n]
  if n in [0,10]:
   d.polygon([(5,14),(21,5),(28,10),(27,20),(10,28),(4,24)],fill='#493c36');d.polygon([(6,14),(21,7),(26,11),(11,20)],fill=color);d.ellipse((5,15,15,27),fill=color);d.ellipse((8,18,12,24),outline='#6b503c',width=1)
  elif n in [1,5]:
   d.ellipse((5,7,28,27),fill='#3b514e');d.ellipse((8,8,25,24),fill=color);d.ellipse((12,10,18,15),fill='#d9edd0');d.line((10,23,15,24),fill='#648574',width=2)
  else:
   d.polygon([(3,24),(8,14),(10,6),(17,3),(21,12),(26,8),(29,25),(21,29),(9,29)],fill='#363c4b');d.polygon([(10,7),(16,5),(19,15),(15,26),(7,24)],fill=color);d.polygon([(20,16),(25,11),(27,24),(20,27)],fill=color);d.line((13,8,12,19),fill='#e8e5c5',width=1);d.line((23,16,22,23),fill='#e8e5c5',width=1)
 elif index in [40,41]:
  c='#df7c82' if index==40 else '#72b8d8';d.rectangle((12,3,20,7),fill='#bea476');d.rectangle((11,7,21,14),fill='#a3b7bd');d.ellipse((6,12,26,29),fill='#455767');d.ellipse((8,15,24,27),fill=c);d.rectangle((12,10,19,14),fill=c);d.line((10,17,10,22),fill='#e8e8d6',width=2);d.rectangle((14,19,18,21),fill='#ead7a6');d.rectangle((15,18,16,23),fill='#ead7a6')
 else:
  d.polygon([(16,3),(28,16),(16,29),(4,16)],fill='#bd9b6e');d.polygon([(16,7),(24,16),(16,25),(8,16)],fill='#737e79');d.line((16,10,16,22),fill='#e0d2a3',width=2);d.line((10,16,22,16),fill='#e0d2a3',width=2)
 atlas.paste(im,((index%8)*32,(index//8)*32))
atlas.save(out/'atlas.png');(out/'LICENSE.md').write_text('Original NowRift procedural item artwork. Generated by scripts/generate-items.py. CC0 1.0 Universal. No reference assets were copied.\n')
print('Generated 48 original equipment, jewelry, material and tonic icons.')
